  writeFileSync(outPath, JSON.stringify(packageData, null, 2));
  writeFileSync(join(EVIDENCE_DIR, 'latest.json'), JSON.stringify(packageData, null, 2));

  return { artifacts, packageHash, generatedAt: packageData.generatedAt };
}

