import json, time, hashlib, sys, os

PRODUCTION_API = 'https://api.ivxholding.com'
LANDING_URL = 'https://ivxholding.com'
RUNNER_VERSION = 'ivx-qa-v1.0.0'

def fetch_json(url, opts=None, timeout=15):
    import urllib.request
    h = {'Content-Type': 'application/json'}
    body = None
    if opts:
        if opts.get('headers'): h.update(opts['headers'])
        if opts.get('body'): body = opts['body'].encode('utf-8')
    method = opts.get('method', 'GET') if opts else 'GET'
    req = urllib.request.Request(url, data=body, headers=h, method=method)
    try:
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            return resp.status, json.loads(resp.read().decode('utf-8'))
    except Exception as e:
        return getattr(e, 'code', 0), {'error': str(e)}

def fetch_status(url, timeout=10):
    import urllib.request
    try:
        req = urllib.request.Request(url, method='GET')
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            return resp.status
    except Exception as e:
        return getattr(e, 'code', 0)

def hash_str(s):
    h = 0
    for c in s:
        h = ((h << 5) - h + ord(c)) & 0xFFFFFFFF
    return f'h{h:08x}'

# Get owner token
print("Authenticating...")
status, auth = fetch_json(f'{PRODUCTION_API}/api/ivx/owner-passwordless-login', {
    'method': 'POST',
    'body': json.dumps({'email': 'iperez4242@gmail.com', 'emergency': 'ivx_emergency_recovery'})
})
token = auth.get('accessToken', '')
if not token:
    print(f"AUTH FAILED: {auth}")
    sys.exit(1)
print(f"Token OK (len={len(token)})")

# Get production SHA
status, health = fetch_json(f'{PRODUCTION_API}/health')
prod_sha = health.get('commit', 'unknown')
print(f"Production SHA: {prod_sha[:12]}")

results = []

def run_test(test_id, category, name, expected, fn):
    start = time.time()
    try:
        outcome = fn()
        elapsed = int((time.time() - start) * 1000)
        result = {
            'testId': test_id, 'category': category, 'name': name,
            'expected': expected, 'actual': outcome.get('actual', ''),
            'status': outcome.get('status', 'FAIL'),
            'timestamp': time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime()),
            'commitSha': prod_sha[:12], 'evidenceRef': outcome.get('evidenceRef', ''),
            'durationMs': elapsed,
        }
        if outcome.get('errorDetail'):
            result['errorDetail'] = outcome['errorDetail']
    except Exception as e:
        elapsed = int((time.time() - start) * 1000)
        result = {
            'testId': test_id, 'category': category, 'name': name,
            'expected': expected, 'actual': 'Exception', 'status': 'ERROR',
            'timestamp': time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime()),
            'commitSha': prod_sha[:12], 'evidenceRef': 'exception',
            'durationMs': elapsed, 'errorDetail': str(e)[:300],
        }
    results.append(result)
    print(f"[{result['status']}] {test_id} — {name} ({result['durationMs']}ms)")
    if result.get('errorDetail'):
        print(f"         {result['errorDetail'][:150]}")
    time.sleep(1)

# === CONVERSATION ===
def t_conv_001():
    s, d = fetch_json(f'{PRODUCTION_API}/api/public/chat', {
        'method': 'POST', 'body': json.dumps({'message': 'What is 2 plus 3?'})
    })
    answer = str(d.get('answer', ''))
    return {'actual': f'HTTP {s}, answer len={len(answer)}, ok={d.get("ok")}',
            'status': 'PASS' if s == 200 and len(answer) > 0 else 'FAIL',
            'evidenceRef': 'public-chat-response'}
run_test('QA-CONV-001', 'conversation', 'IVX IA responds to technical question', 'Non-empty answer from public chat', t_conv_001)

def t_conv_002():
