def fetch_json(url, opts=None, timeout=15):
    import urllib.request
    h = {'Content-Type': 'application/json'}
    body = None
    if opts:
        if opts.get('headers'): h.update(opts['headers'])
        if opts.get('body'): body = opts['body'].encode('utf-8')
    method = opts.get('method', 'GET') if opts else 'GET'
    req = urllib.request.Request(url, data=body, headers=h, method=method)
    try:
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            return resp.status, json.loads(resp.read().decode('utf-8'))
    except Exception as e:
        return getattr(e, 'code', 0), {'error': str(e)}

def fetch_status(url, timeout=10):
    import urllib.request
    try:
        req = urllib.request.Request(url, method='GET')
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            return resp.status
    except Exception as e:
        return getattr(e, 'code', 0)

def hash_str(s):
    h = 0
    for c in s:
        h = ((h << 5) - h + ord(c)) & 0xFFFFFFFF
    return f'h{h:08x}'

